content:
{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Ensure VNET subnet is configured with a Network Security Group (NSG)",
      "resource": "azurerm_subnet.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet 'healthcare-patient-portal-with-hipaa-compliance-subnet-data' is not associated with a Network Security Group (NSG), potentially exposing it to unauthorized access."
    }
  ],
  "patched_code": "resource "azurerm_network_security_group" "data_subnet_nsg" {
  name                = "healthcare-patient-portal-with-hipaa-compliance-subnet-data-nsg"
  location            = azurerm_resource_group.healthcare_portal.location
  resource_group_name = azurerm_resource_group.healthcare_portal.name

  security_rule {
    name                       = "default_rule"
    priority                   = 1000
    direction                  = "Inbound"
    access                     = "Allow"
    protocol                   = "*"
    source_port_range          = "*"
    destination_port_range     = "*"
    source_address_prefix      = "*"
    destination_address_prefix = "*"
  }
}

resource "azurerm_subnet_network_security_group_association" "data_subnet_nsg_assoc" {
  subnet_id                 = azurerm_subnet.data_subnet.id
  network_security_group_id = azurerm_network_security_group.data_subnet_nsg.id
}

resource "azurerm_subnet" "data_subnet" {
  name                 = "healthcare-patient-portal-with-hipaa-compliance-subnet-data"
  resource_group_name  = azurerm_resource_group.healthcare_portal.name
  virtual_network_name = azurerm_virtual_network.healthcare_vnet.name
  address_prefixes     = ["10.0.3.0/24"]
}",
  "fix_summary": "Added a Network Security Group (NSG) and associated it with the subnet 'healthcare-patient-portal-with-hipaa-compliance-subnet-data' to control inbound and outbound traffic."
}
